#include <cstdio>

int main() {
    long long a, x, y;
    scanf("%lld%lld%lld", &a, &x, &y);

    if (a <= 0 || y <= 0 || y % a == 0) {
        printf("-1");
        return 0;
    }

    long long level = y / a;

    if (level == 0) {
        if (-a < 2 * x && 2 * x < a)
            printf("1");
        else
            printf("-1");
    } else if (level % 2 == 1) {
        if (-a < 2 * x && 2 * x < a)
            printf("%lld", level + level / 2 + 1);
        else
            printf("-1");
    } else {
        long long left = 3 * level / 2;
        if (-a < x && x < 0)
            printf("%lld", left);
        else if (0 < x && x < a)
            printf("%lld", left + 1);
        else
            printf("-1");
    }

    return 0;
}

#include <cstdio>

int main() {
    long long a, x, y;
    scanf("%lld%lld%lld", &a, &x, &y);

    if (a <= 0 || y <= 0 || y % a == 0 || 2 * x == -a || 2 * x == a) {
        printf("-1");
        return 0;
    }

    if (y < a) {
        printf((-a < 2 * x && 2 * x < a) ? "1" : "-1");
        return 0;
    }

    long long floor = y / a;
    long long base = (3 * floor - 1) / 2;

    if (floor % 2 == 1) {
        if (-a < 2 * x && 2 * x < a)
            printf("%lld", base + 1);
        else
            printf("-1");
    } else {
        if (-a < x && x < 0)
            printf("%lld", base + 1);
        else if (0 < x && x < a)
            printf("%lld", base + 2);
        else
            printf("-1");
    }

    return 0;
}

