int main()
{
    long long a, x, y;
    scanf("%lld%lld%lld", &a, &x, &y);

    if (y <= 0 || x * 2 == -a || x * 2 == a)
    {
        printf("-1");
        return 0;
    }

    if (y < a)
    {
        printf((-a < x * 2 && x * 2 < a) ? "1" : "-1");
        return 0;
    }

    if (y % a == 0)
    {
        printf("-1");
        return 0;
    }

    long long i = y / a;
    long long save = (3 * i - 1) / 2;

    if (i % 2 == 1)
    {
        if (-a < x * 2 && x * 2 < a)
        {
            printf("%lld", save + 1);
            return 0;
        }
    }
    else
    {
        if (-a < x && x < 0)
        {
            printf("%lld", save + 1);
            return 0;
        }
        if (0 < x && x < a)
        {
            printf("%lld", save + 2);
            return 0;
        }
    }

    printf("-1");
    return 0;
}

